"""GVFC frame definitions used in the published experiments.

The binary indicators are the 91 descriptive items reported in Appendix B.
"""

FRAME_ORDER = ['Rights', 'Control', 'Politics', 'Health', 'Safety', 'Race', 'Opinion', 'Social', 'Economic']
FRAME_TO_ID = {name: i + 1 for i, name in enumerate(FRAME_ORDER)}
ID_TO_FRAME = {v: k for k, v in FRAME_TO_ID.items()}

BINARY_ITEMS = {'Rights': ['the Constitution or the second amendment', 'the protection of individual liberty', 'the protection of gun ownership as a right', 'The Meaning of the 2nd amendment', 'The irrefutability of one’s right to own guns', 'Gun ownership as critical to democracy', 'Gun ownership as critical to protecting oneself'], 'Control': ['regulating guns through legislation', 'regulating guns through institutional measures', 'Enforcing background checks', 'expanding background checks', 'Limiting sales of guns', 'Limiting sales of dangerous equipment', 'Increasing age limits on gun purchases', 'Implementing licensing', 'Implementing gun safety training programs'], 'Politics': ['the political issues around guns', 'the political issues around shootings', 'Political campaigns', 'upcoming elections', 'Fighting between the Democratic and Republican parties', 'Fighting between the Democratic and Republican politicians', 'Democratic and Republican politicians', 'Democratic and Republican parties', 'Political money contributions from gun lobbies', 'Political money contributions', 'gun lobbies', 'One political party or one politician’s stance on gun violence', "One political party's stance on gun violence", 'One politician’s stance on gun violence', 'A politician', 'A political party'], 'Health': ['an individuals’ emotional well-being', 'an individuals’ mental illnesses', 'the mental health system', 'predicting mental health breakdowns', 'preventing mental health breakdowns', 'Treating mental illness', 'Creating measures to ensure mentally ill people do not have access to guns', 'measures to ensure mentally ill people do not have access to guns', 'an individuals’ personality traits that indicate instability', 'an individuals’ personality traits that indicate impulsivity', 'an individuals’ personality traits that indicate anger', 'an individuals’ behavioral traits that indicate instability', 'an individuals’ behavioral traits that indicate impulsivity', 'an individuals’ behavioral traits that indicate anger'], 'Safety': ['institutional safety', 'school safety', 'Awareness and monitoring of "troubled" individuals by law enforcement', 'Awareness of "troubled" individuals by law enforcement', 'monitoring of "troubled" individuals by law enforcement', 'Awareness of "troubled" individuals', 'monitoring of "troubled" individuals', 'Safety measures in schools to prevent or mitigate shootings', 'Safety measures in schools', 'prevent or mitigate shootings'], 'Race': ['gun issues related to certain ethnic group(s)', 'Angry white men as primary perpetrators of domestic gun violence', 'isolated white men as primary perpetrators of domestic gun violence', 'Immigrants from Mexico bringing in guns', 'Immigrants from Mexico from across the border', 'Muslim "terrorists"', 'Gun violence in African American communities'], 'Opinion': ['the public’s reactions to gun-related issues', 'the public’s reactions', 'a certain community’s reactions to gun-related issues', 'a certain community’s reactions', 'Public opinion polls related to guns', 'Public opinion polls', 'protests', 'mourning victims of violence', 'mourning of victims', 'the public’s emotional responses'], 'Social': ['Societal-wide factors related to gun violence', 'Societal-wide factors', 'violence in media', 'Social pressures that may incite someone to violence', 'Social pressures', 'Breakdown in family structures', 'a lack of familial support and stability', 'Breakdown in community structures', 'a lack of community support and stability'], 'Economic': ['financial gains involved in gun-related issues', 'financial losses involved in gun-related issues', 'the costs involved in gun-related issues', 'financial gains, losses or costs', 'The sales of firearms', 'The financial consequences of gun regulation', 'The financial state of gun-related lobbying groups', 'Federal budget for gun-related programs', 'Financial consequences']}

FULL_DESCRIPTIONS = {'Rights': 'Gun rights: The story is related to the Constitution, the second amendment, and protection of individual liberty and gun ownership as a right, including:\n- Meaning of the 2nd amendment\n- The irrefutability of one’s right to own guns\n- Gun ownership as critical to democracy and protecting oneself\nExample: “Membership, interest in gun rights groups soar in the weeks after the Florida high school shooting”\nExample: “Rapper ‘Killer Mike,’ NRA host Colion Noir: No guns would turn people into slaves”', 'Control': 'Gun control: The story is about issues related to regulating guns through legislation and other institutional measures.\n- Enforcing and/or expanding background checks\n- Limiting sale of guns and/or related dangerous equipment (e.g., AR15s, semi-automatic rifles, bump stocks, large-capacity ammo)\n- Increasing age limits on gun purchases\n- Implementing licensing and gun safety training programs\nExample: “GOP lawmaker calls for age restriction on AR-15s”\nExample: “No bump stocks turned in to Denver police after ban”', 'Politics': "Politics: The story is mainly about the political issues around guns and shootings, including:\n- Political campaigns and upcoming elections (e.g., using guns as a wedge issue or motivating force to get people to the polls)\n- Fighting between the Democratic and Republican parties, or politicians\n- Political money contributions from gun lobbies (e.g., NRA)\n- One political party or one politician’s stance on gun violence. Therefore, as long as the news headline mentions a politician’s name, it often indicates the theme of politics.\n- Often times, the politicians’ names or the party names should be mentioned.\nExample: “How Illinois governor candidates would address gun violence”\nExample: “Trump warns Dems will 'take away your Second Amendment'”\nExample: “Lindsey Graham: Both parties will suffer if Congress doesn't act on new gun bill”", 'Health': 'Mental health: The story is about issues related to individuals’ mental illnesses or emotional well-being, or the mental health system as a whole, including:\n- Predicting and preventing mental health breakdowns\n- Treating mental illness\n- Creating measures to ensure mentally ill people do not have access to guns\n- Descriptions of individuals’ behavioral / personality traits that indicate instability, impulsivity, anger, etc.\nExample: “Gun debate hits home for families dealing with myths about violence, mental illness”\nExample: “Renewed Debate Over Gun Access, Mental Health”\nExample: “Las Vegas gunman lost money, became unstable before shooting”', 'Safety': 'Public/school safety: Issues related to institutional and school safety, including:\n- Awareness and monitoring of “troubled” individuals by law enforcement (e.g., local police, FBI)\n- Safety measures in schools to prevent or mitigate shootings (e.g., police/safety officers in the school, armed teachers, metal detectors, clear backpacks)\n- Note that a headline simply mentioning “school shooting” does not necessarily mean it uses this safety measure frame.\nExample: “Preschoolers among students required to carry clear backpacks in Texas school district”\nExample: “Scott wants armed police at Stoneman Douglas after disturbing incidents at Parkland school”\nExample: “Sales of bulletproof school supplies spike after Florida shooting”', 'Race': "Race/ethnicity: The story is about gun issues related to certain ethnic group(s), including:\n- Angry, isolated white men as primary perpetrators of domestic gun violence\n- Immigrants from Mexico bringing in guns from across the border\n- Muslim “terrorists”\n- Gun violence in African American communities\nExample: “Illegal immigrant acquitted of Kate Steinle's murder faces judge on gun charges”\nExample: “The disparities in how black and white men die in gun violence, state by state”", 'Opinion': 'Public opinion: The study is about the public’s, including a certain community’s reactions to gun-related issues, including:\n- Public opinion polls related to guns\n- Protests\n- Mourning victims of gun violence\n- The public’s emotional responses\nExample: “Baltimore students walk out of class to protest gun violence”', 'Social': "Social/cultural issues: Societal-wide factors that are related to gun violence, including:\n- Violence in media (e.g., TV/movies and video games)\n- Social pressures that may incite someone to violence (e.g., cliques/bullying and isolation)\n- Breakdown in family structures, so there is a lack of familial support and stability\n- Breakdown in community structures (e.g., religious organizations, other civic-oriented groups), so there is a lack of community support and stability\nExample: “There's Not A Single Ounce Of Evidence To Link Mass Shootings To Video Games”", 'Economic': 'Economic consequences: The story is about financial losses or gains, or the costs involved in gun-related issues, including:\n- The actual sales of firearms\n- The financial consequences of gun regulation (e.g., lost tax revenue, or gun manufacturing companies moving to a different state)\n- The financial state of gun-related lobbying groups (e.g., the NRA)\n- Federal budget for gun-related programs\nExample: “The NRA Is In Deep, Deep Financial Trouble”'}

ALL_BINARY_ITEMS = [item for frame in FRAME_ORDER for item in BINARY_ITEMS[frame]]
ITEM_TO_FRAME = {item: frame for frame, items in BINARY_ITEMS.items() for item in items}

assert len(ALL_BINARY_ITEMS) == 91

# The original experiment code evaluated eight preliminary items before the
# 91 frame-specific indicators. These items were used for relevance/focus
# bookkeeping in the historical 99-statement raw outputs but are not part of
# Appendix B or the paper's reported nine-frame evaluation.
PRELIMINARY_ITEMS = {
    "Related": ["gun-violence related issue"],
    "Episodic": ["a specific incident or event of gun violence or shooting"],
    "Thematic": [
        "causes of gun violence",
        "consequences of gun violence",
        "causes of shootings",
        "consequences of shootings",
        "solutions to gun violence",
        "solutions to shootings",
    ],
}

HISTORICAL_FRAME_ORDER = ["Related", "Episodic", "Thematic"] + FRAME_ORDER
HISTORICAL_ITEMS_BY_FRAME = {**PRELIMINARY_ITEMS, **BINARY_ITEMS}
ALL_HISTORICAL_ITEMS = [
    item for frame in HISTORICAL_FRAME_ORDER for item in HISTORICAL_ITEMS_BY_FRAME[frame]
]
HISTORICAL_ITEM_TO_FRAME = {
    item: frame for frame, items in HISTORICAL_ITEMS_BY_FRAME.items() for item in items
}

assert len(ALL_HISTORICAL_ITEMS) == 99
